from lesson_helpers import *
labels=['Anomalies glomérulaires mineures','Lésions glomérulaires segmentaires et focales','Glomérulonéphrite membraneuse diffuse','Glomérulonéphrite mésangio-proliférative diffuse','Glomérulonéphrite proliférative endocapillaire diffuse','Glomérulonéphrite mésangiocapillaire diffuse','Maladie à dépôt dense','Glomérulonéphrite diffuse en croissant','Autres modifications morphologiques','Type de modification morphologique non précisé']
body='''<p>Le diagnostic clinique précède le codage. Les suffixes ci-dessous sont ceux du modificateur morphologique OFS appliqué à N02. Ils ne représentent ni dix stades cliniques ni dix prescriptions. Les suffixes .0 à .8 nécessitent normalement une identification précise par biopsie ou autopsie. Un variant COL4 ou une IgA soupçonnée ne permettent pas d’inventer une morphologie.</p>'''+table(['Sous-code','Libellé morphologique OFS'],[['N02.'+str(i),x] for i,x in enumerate(labels)])+'''<p>R31 décrit l’hématurie sans autre indication, hors N02 ; N39.81 correspond au syndrome du flanc douloureux avec hématurie exclu de cette catégorie. Les indications de biopsie viennent de la clinique et des recommandations applicables, jamais de la volonté de remplir un suffixe. La catégorie historique inclut le terme « bénigne » ; le cours conserve le libellé comme information administrative et n’en fait pas un pronostic.</p>'''
p=CH/'N02_b.html';txt=p.read_text();end=txt.rfind('</div></div>');assert end>0;p.write_text(txt[:end]+sec('annexe-cim','Après la conclusion clinique : sous-codes morphologiques',body,('CH-CIM',))+txt[end:])
# Definitions remain conditional and local; no existing glossary key is replaced.
g='from cardio_1 import a, G\n# N02 — définitions et sigles propres ; sources dans le ledger N02.\n'
entries=[('MEST-C','Score morphologique Oxford de l’IgA','M : hypercellularité mésangiale ; E : endocapillaire ; S : sclérose segmentaire ; T : fibrose interstitielle et atrophie tubulaire ; C : croissants. Ce score ne décide pas seul du traitement.','n02-exp-8'),('CUEN','Collège universitaire des enseignants de néphrologie','Référence française utilisée pour la sémiologie ; son seuil est attribué et distinct du laboratoire HUG.','n02-exp-8'),('ERKNet','European Reference Network for Rare Kidney Diseases','Réseau européen participant au guide Alport avec ERA et ESPN.','n02-exp-11'),('ESPN','European Society for Paediatric Nephrology','Société européenne de néphrologie pédiatrique, participante au guide Alport consulté.','n02-exp-11'),('MEBEKO','Commission des professions médicales','Exigences de l’examen fédéral 2026 consultées ; exercices MEDINA originaux, sans statut officiel.','n02-exp-13'),('N39.81','Syndrome du flanc douloureux avec hématurie','Catégorie exclue de N02 dans la CIM-10-GM OFS consultée.','n02-exp-1')]
for k,title,desc,ref in entries:g+='if '+repr(k)+' not in G:\n    a('+repr(k)+', [('+repr(k)+', '+repr(title)+')], '+repr(title)+', '+repr('<p>'+desc+'</p>')+', '+repr(ref)+')\n'
(ROOT/'glossary/n02.py').write_text(g)
